import React from 'react';
import type { CalendarMode, DisabledDateFilter, IDateRangePickerA11yLabels, IWalmartWeekRange } from '../../types';
/**
 * Props for DvDateRangePickerPanel — the embedded/inline date range picker
 * that can be used inside custom containers (like Boards Time Filter).
 */
export interface IDvDateRangePickerPanelProps {
    /** Current start date of the range */
    startDate?: Date | null;
    /** Current end date of the range */
    endDate?: Date | null;
    /**
     * Called when user selects dates in calendar or dropdowns
     * (before Apply is clicked — useful for live preview)
     */
    onChange?: (range: {
        startDate: Date | null;
        endDate: Date | null;
    }) => void;
    /** Called when user clicks Apply button */
    onApply?: (range: {
        startDate: Date;
        endDate: Date;
    }) => void;
    /** Called when user clicks Cancel button */
    onCancel?: () => void;
    /**
     * Calendar mode: 'standard' (day selection) or 'walmart' (week selection)
     * @default 'standard'
     */
    calendarMode?: CalendarMode;
    /**
     * Show fiscal year section headers in week dropdowns (Walmart mode only).
     * @default false
     */
    showFiscalYearHeaders?: boolean;
    /**
     * Show month/year section headers (e.g. "January 2026") in week dropdowns.
     * Weeks are grouped by the calendar month of their start date.
     * When a week spans two months, it appears under the month of its start date.
     * @default false
     */
    showMonthYearHeaders?: boolean;
    /**
     * Callback when a week range is selected (Walmart mode only)
     */
    onWeekSelect?: (range: IWalmartWeekRange) => void;
    /** Label for the start week dropdown (Walmart mode). Default: 'Start week (Walmart week #)' */
    startWeekLabel?: string;
    /** Label for the end week dropdown (Walmart mode). Default: 'End week (Walmart week #)' */
    endWeekLabel?: string;
    /** Minimum selectable date (Date object or timestamp) */
    minDate?: Date | number;
    /** Maximum selectable date (Date object or timestamp) */
    maxDate?: Date | number;
    /** Function to determine if a date should be disabled */
    disabledDateFilter?: DisabledDateFilter;
    /**
     * Show Clear All link
     * @default true
     */
    showClearAll?: boolean;
    /** Label for Clear All link */
    clearAllLabel?: string;
    /** Called when Clear All is clicked */
    onClearAll?: () => void;
    /** Locale for date formatting */
    /**
     * Locale string for date formatting and calendar display.
     * If not provided, uses the active i18next locale from useDatePickerTranslations.
     *
     * @default Resolved from i18next (typically 'en-US', 'es-MX', or 'fr-CA')
     */
    locale?: string;
    /** Accessibility labels */
    a11yLabels?: IDateRangePickerA11yLabels;
    /** Additional class name */
    className?: string;
    /** Whether the panel is disabled */
    disabled?: boolean;
    /**
     * Whether to show the drop shadow on the panel.
     * Set to `false` when the panel is embedded inside a container
     * that provides its own elevation/border (e.g., a modal or sidebar).
     * @default true
     */
    overlay?: boolean;
}
/**
 * DvDateRangePickerPanel — Embedded/inline date range picker panel.
 *
 * Unlike `DvDateRangePicker` which uses a popover, this component renders
 * the calendar and dropdowns inline (always visible). It's designed to be
 * used inside custom containers like the Boards Time Filter.
 *
 * ```tsx
 * // Walmart mode (week selection)
 * <DvDateRangePickerPanel
 *   calendarMode="walmart"
 *   startDate={startDate}
 *   endDate={endDate}
 *   onChange={({ startDate, endDate }) => {
 *     setStartDate(startDate);
 *     setEndDate(endDate);
 *   }}
 *   onApply={handleApply}
 *   onCancel={handleCancel}
 * />
 *
 * // Standard mode (day selection)
 * <DvDateRangePickerPanel
 *   calendarMode="standard"
 *   startDate={startDate}
 *   endDate={endDate}
 *   onChange={handleChange}
 *   onApply={handleApply}
 * />
 * ```
 */
export declare const DvDateRangePickerPanel: React.ForwardRefExoticComponent<IDvDateRangePickerPanelProps & React.RefAttributes<HTMLDivElement>>;
